const a={async increment(e,t){if(!t||!e)return;const n=`viewed_${e}_${t}`;if(sessionStorage.getItem(n))return;const i=window.APP_CONFIG?.baseUrl||"/",c=`view-${e}-views-count`,s=document.getElementById(c);try{const r=await(await fetch(`${i}api/views-increment`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:e,id:t})})).json();r.success&&s&&(s.textContent=r.newCount,sessionStorage.setItem(n,"true"))}catch(o){console.error(`[ViewCounter] Failed to increment ${e} view:`,o)}}};export{a as V};
